import { Component, h, Prop, Event, EventEmitter, Element, State, Watch, Host } from '@stencil/core';
import { Provide } from '@src/framework/runtime-context';
import classnames from 'classnames';
import { RadioValue } from '@src/components/ks-radio/types';
import { Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { RadioGroupContext, RadioGroupContextValue } from '@src/components/ks-radio/context';
import { FormContextValueReconcile } from '@src/components/ks-form/FormContextValueReconcile';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { formatCSSLength } from '@src/shared/dom';
import { generateUniqueId } from '@src/shared/unclassified/unique-id';

const prefix = 'radio-group';

/**
 * @slot default - The slot for the radio buttons inside the group.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-radio-group',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsRadioGroup extends FormBaseComponent<RadioValue> {
  protected static vModel = { prop: 'value', event: 'ksChange' };
  @Element() el!: HTMLKsRadioGroupElement;

  @Provide({
    context: RadioGroupContext,
  })
  private radioGroupContext: RadioGroupContextValue = {
    htmlName: undefined,
    disabled: undefined,
    value: undefined,
    onValueChange: (value: RadioValue) => {
      this.internalValueState = value;
    },
  };

  /** The name attribute of the radio inside the group. */
  @Prop() htmlName = generateUniqueId();
  /** Indicates whether the entire radio group is disabled. When `true`, all radio buttons within the group will be inactive and unselectable. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** The current value of the selected radio button in the group. This represents the selected option ID in the radio group. */
  @Prop() @Vue2ValueFix() @FormContextValueReconcile() value?: RadioValue;
  /** The default value of the radio group when the component is first rendered. */
  @Prop() defaultValue?: RadioValue;
  @Uncontrollable('value', 'defaultValue', 'ksChange') @State() internalValueState?: RadioValue;
  /** Indicates whether the radio buttons in the group should be arranged vertically. When `true`, the radio buttons will be stacked in a vertical layout. */
  @Prop() orientation: 'vertical' | 'horizontal' = 'horizontal';

  /** The gap between radio buttons in the group. */
  @Prop() gap?: string | number;

  /** Custom event triggered when the selected radio button in the group changes. This event can be used to execute additional actions upon selection change. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<RadioValue>;

  // eslint-disable-next-line @typescript-eslint/no-useless-constructor
  constructor() {
    super();
  }

  @Watch('htmlName')
  @Watch('disabled')
  @Watch('internalValueState')
  handleContextValueChange() {
    this.radioGroupContext = {
      ...this.radioGroupContext,
      htmlName: this.htmlName,
      disabled: this.disabled,
      value: this.internalValueState,
    };
  }

  componentWillLoad() {
    this.handleContextValueChange();
  }

  render() {
    const classes = classnames([`${prefix}`, `${prefix}--${this.orientation}`]);
    return (
      <Host class="KsRadioGroup">
        <div
          class={classes}
          style={{
            gap: formatCSSLength(this.gap),
          }}
          part="base"
        >
          <slot></slot>
        </div>
      </Host>
    );
  }
}
